
function labFlood(board,start,w,equal=true){const value=board[start],seen=[start];for(let k=0;k<seen.length;k++)for(let i=0;i<board.length;i++)if(!seen.includes(i)&&labAdjacent(seen[k],i,w)&&(equal?board[i]===value:board[i]>0))seen.push(i);return seen;}
function labMergeSpawn(d){const empty=d.board.map((v,i)=>v===0?i:-1).filter(i=>i>=0);if(!empty.length)return false;const r=labRand(d.seed++*7919);d.board[empty[Math.floor(r()*empty.length)]]=r()<.9?2:4;return true;}
function labSlideNumbers(board,w,dir){const next=Array(board.length).fill(0);for(let line=0;line<w;line++){const ids=Array.from({length:w},(_,k)=>dir===0?k*w+line:dir===2?(w-1-k)*w+line:dir===3?line*w+k:line*w+w-1-k),vals=ids.map(i=>board[i]).filter(Boolean),out=[];for(let k=0;k<vals.length;k++){if(vals[k]===vals[k+1]){out.push(vals[k]*2);k++;}else out.push(vals[k]);}ids.forEach((i,k)=>next[i]=out[k]||0);}return next;}
function labTile(v){return v?'<span class="lab-merge-tile" style="--tile:'+LAB_COLORS[(Math.round(Math.log2(v))||v)%6]+'">'+v+'</span>':'·';}
LAB_ENGINES.merge={
 init(c,seed){const v=c.variant,r=labRand(seed*7919),d={w:4,seed,target:32,selected:[],undo:[],score:0};
 if(['slide','drop','sticky'].includes(v)){d.board=Array(16).fill(0);d.board[12]=2;d.board[13]=2;d.next=2;}
 if(v==='dice'||v==='get'){d.board=Array.from({length:16},()=>1+Math.floor(r()*3));d.next=1+seed%3;d.target=v==='dice'?6:7;}
 if(v==='eat'){d.board=labShuffle([1,9,2,8,3,7,4,6,5,5,2,8,3,7,4,6],r);d.target=8;}
 if(v==='jelly'){d.board=[1,0,0,1,0,-1,0,0,2,0,0,2,3,0,0,3];d.goal=3;}
 if(v==='mergix'){d.w=3;d.board=Array(9).fill(0);d.next=1;d.target=5;}
 if(['water','hexa'].includes(v)){d.capacity=4;d.tubes=[[1,2,1,2],[2,1,2,1],[],[]];if(seed%2)d.tubes=[[1,2,3,1],[2,3,1,2],[3,1,2,3],[],[]];d.selected=null;}
 if(['tile','bus','car'].includes(v)){d.board=labShuffle([1,1,1,2,2,2,3,3,3,4,4,4],r);d.tray=[];d.limit=v==='bus'?5:7;d.bus=1;d.delivered=0;d.target=12;d.directions=d.board.map((_,i)=>i%4);}
 return d;
 },
 render(d,c){const v=c.variant;if(['water','hexa'].includes(v))return '<p>Tap a source, then a destination. Move the top colour onto the same colour or an empty '+(v==='water'?'bottle':'stack')+'. Sort every colour together.</p><div class="lab-tubes">'+d.tubes.map((t,i)=>labButton('tube','<span class="lab-tube '+(d.selected===i?'lab-selected':'')+'">'+Array.from({length:4},(_,k)=>'<i style="background:'+(t[3-k]?LAB_COLORS[t[3-k]-1]:'transparent')+'">'+(t[3-k]||'')+'</i>').join('')+'</span>',i)).join('')+'</div>'+labButton('undo','Undo pour');
 if(['tile','bus','car'].includes(v))return '<div class="lab-callout">'+d.delivered+' / 12 cleared</div><p>'+({tile:'Choose tiles. Three of a kind clear the tray. Do not fill all seven spaces.',bus:'Bus '+d.bus+' is boarding. Select passengers; others wait in the five-space queue. Fill this bus with three matching passengers.',car:'Tap a car to rotate its arrow. Release it when its lane is clear. Three matching cars clear the seven-space parking tray.'})[v]+'</p>'+labGrid(d.board,4,(x,i)=>x?'<span style="color:'+LAB_COLORS[x-1]+'">'+(['🐱','🐶','🐸','🦊'][x-1])+(v==='car'?['↑','→','↓','←'][d.directions[i]]:'')+'</span>':'·')+(v==='car'?labButton('release','Release selected car'):'')+'<div class="lab-tray">'+(d.tray.map(x=>['🐱','🐶','🐸','🦊'][x-1]).join(' ')||'Waiting tray')+' · '+d.tray.length+'/'+d.limit+'</div>'+labButton('undo','Undo');
 return '<div class="lab-callout">'+(v==='eat'?d.score+' / 8 meals':v==='mergix'?d.score+' / 5 lines':v==='jelly'?'Merge each colour into one jelly':'Build a '+d.target+' tile')+'</div><p>'+({slide:'Swipe with the arrows. Equal numbers merge once per move.',drop:'Choose a column to drop the next tile. Equal neighbours merge into it.',sticky:'Select an equal neighbouring pair to merge them, then a fresh tile appears.',dice:'Select a group of at least three equal dice. They merge into the next value.',get:'Select two or more equal connected tiles. They become one higher tile.',eat:'Select numbers that add to ten, then feed the hungry monster.',jelly:'Tilt to slide all jellies. Equal colours stick together; rocks stay still.',mergix:'Place coloured tiles. Three equal colours in a row or column clear a line. Layering a tile cycles its colour.'})[v]+'</p>'+labGrid(d.board,d.w,(x,i)=>'<span class="'+(d.selected.includes(i)?'lab-selected':'')+'">'+(x<0?'🪨':labTile(x))+'</span>')+(['slide','jelly'].includes(v)?labOptions('move',['↑','→','↓','←']):v==='eat'?labButton('feed','Feed ten 🍽'):v==='dice'||v==='get'?labButton('combine','Merge group'):v==='drop'?'<p>Next tile: '+d.next+'</p>':v==='mergix'?'<p>Next colour: '+d.next+'</p>':'')+labButton('undo','Undo move');
 },
 action(d,a,n,c){const v=c.variant;if(a==='undo'&&d.undo.length){Object.assign(d,JSON.parse(d.undo.pop()));return;}const save=()=>{const copy={...d};delete copy.undo;d.undo.push(JSON.stringify(copy));};
 if(['water','hexa'].includes(v)&&a==='tube'){if(!d.tubes[n])return;if(d.selected===null){if(d.tubes[n].length)d.selected=n;return;}const from=d.tubes[d.selected],to=d.tubes[n];if(n===d.selected){d.selected=null;return;}if(to.length>=4||to.length&&to.at(-1)!==from.at(-1)){labMiss('Pour onto the same colour or an empty space.');return;}save();const color=from.at(-1);do{to.push(from.pop());}while(v==='water'&&from.at(-1)===color&&to.length<4);d.selected=null;game.session.moves++;if(d.tubes.every(t=>!t.length||t.length===4&&t.every(x=>x===t[0])))labWin('Every colour is together!');return;}
 if(['tile','bus','car'].includes(v)){if(v==='car'&&a==='cell'&&d.board[n]){d.selected=[n];d.directions[n]=(d.directions[n]+1)%4;return;}if(v==='car'&&a==='release'){n=d.selected[0];if(n===undefined)return;let i=labNeighbour(n,d.directions[n],4);while(i>=0){if(d.board[i]){labMiss('Another car blocks this lane.');return;}i=labNeighbour(i,d.directions[n],4);}}else if(a!=='cell'||!d.board[n])return;save();d.tray.push(d.board[n]);d.board[n]=0;if(v==='bus'){let again=true;while(again){again=false;const count=d.tray.filter(x=>x===d.bus).length;if(count>=3){d.tray=d.tray.filter(x=>x!==d.bus);d.delivered+=3;d.bus++;again=true;}}}else for(let x=1;x<=4;x++)if(d.tray.filter(k=>k===x).length===3){d.tray=d.tray.filter(k=>k!==x);d.delivered+=3;}game.session.moves++;if(d.delivered===12)labWin('Everyone is safely on their way!');else if(d.tray.length>=d.limit)labLose('The waiting area is full. Try a different order.');return;}
 if(a==='move'&&v==='slide'){const next=labSlideNumbers(d.board,4,n);if(next.join()===d.board.join())return;save();d.board=next;labMergeSpawn(d);game.session.moves++;}
 if(a==='move'&&v==='jelly'){save();const order=Array.from({length:16},(_,i)=>i).sort((a,b)=>n===0?a-b:n===2?b-a:n===1?b%4-a%4:a%4-b%4);for(const i of order){if(d.board[i]<=0)continue;let at=i,next=labNeighbour(at,n,4);while(next>=0&&d.board[next]===0){d.board[next]=d.board[at];d.board[at]=0;at=next;next=labNeighbour(at,n,4);}if(next>=0&&d.board[next]===d.board[at])d.board[at]=0;}game.session.moves++;if([1,2,3].every(x=>d.board.filter(v=>v===x).length===1))labWin('Every jelly found its partner!');return;}
 if(a==='cell'&&v==='drop'){const col=n%4;let at=-1;for(let row=0;row<4;row++){if(d.board[row*4+col])break;at=row*4+col;}if(at<0)return;save();d.board[at]=d.next;let group=labFlood(d.board,at,4);while(group.length>1){d.board[group.find(i=>i!==at)]=0;d.board[at]*=2;const below=Array.from({length:3-Math.floor(at/4)},(_,k)=>at+(k+1)*4).filter(i=>d.board[i]).length;for(let x=0;x<4;x++){const vals=[0,1,2,3].map(y=>d.board[y*4+x]).filter(Boolean);for(let y=0;y<4;y++)d.board[y*4+x]=y<4-vals.length?0:vals[y-(4-vals.length)];}at=(3-below)*4+col;group=labFlood(d.board,at,4);}d.next=labRand(d.seed++*7919)()<.8?2:4;game.session.moves++;}
 if(a==='cell'&&['sticky','dice','get','eat'].includes(v)&&d.board[n]){if(v==='sticky'){if(!d.selected.length){d.selected=[n];return;}const i=d.selected[0];if(i===n){d.selected=[];return;}if(!labAdjacent(i,n,4)||d.board[i]!==d.board[n]){d.selected=[n];return;}save();d.board[n]*=2;d.board[i]=0;d.selected=[];labMergeSpawn(d);game.session.moves++;}else if(v==='eat'){d.selected=d.selected.includes(n)?d.selected.filter(i=>i!==n):[...d.selected,n];return;}else{d.selected=labFlood(d.board,n,4);return;}}
 if(a==='combine'&&['dice','get'].includes(v)){if(d.selected.length<(v==='dice'?3:2)){labMiss('Choose a larger connected group.');return;}save();const at=d.selected[0],value=d.board[at]+1;d.selected.forEach(i=>d.board[i]=0);d.board[at]=value;d.selected=[];for(let i=0;i<16;i++)if(!d.board[i])d.board[i]=1+Math.floor(labRand(d.seed++*7919)()*3);game.session.moves++;}
 if(a==='feed'&&v==='eat'){if(d.selected.reduce((sum,i)=>sum+d.board[i],0)!==10){labMiss('That meal does not add to ten yet.');return;}save();d.selected.forEach(i=>d.board[i]=0);d.selected=[];d.score++;game.session.moves++;if(d.score===8)labWin('Eight perfectly balanced meals!');return;}
 if(a==='cell'&&v==='mergix'){save();d.board[n]=(d.board[n]+d.next-1)%3+1;const lines=[];for(let k=0;k<3;k++)lines.push([k*3,k*3+1,k*3+2],[k,k+3,k+6]);const clear=lines.filter(ids=>d.board[ids[0]]&&ids.every(i=>d.board[i]===d.board[ids[0]]));d.score+=clear.length;new Set(clear.flat()).forEach(i=>d.board[i]=0);d.next=1+Math.floor(labRand(d.seed++*7919)()*3);game.session.moves++;if(d.score>=5)labWin('Five colour lines cleared!');return;}
 if(['slide','drop','sticky','dice','get'].includes(v)&&d.board.some(x=>x>=d.target))labWin('You built the target tile!');else if(v==='slide'&&[0,1,2,3].every(dir=>labSlideNumbers(d.board,4,dir).join()===d.board.join()))labLose('No moves remain. Try another strategy.');else if(v==='drop'&&d.board.every(Boolean))labLose('The board is full. Merge more often to make space.');
 }
};
